CREATE TABLE IF NOT EXISTS git_history_session_change (
             sequence INTEGER PRIMARY KEY AUTOINCREMENT,
             provider TEXT NOT NULL,
             session_id TEXT NOT NULL,
             UNIQUE(provider, session_id)
         );

CREATE TABLE IF NOT EXISTS session_schema_migrations (
            name TEXT NOT NULL PRIMARY KEY,
            version INTEGER NOT NULL,
            applied_at INTEGER NOT NULL DEFAULT (unixepoch())
        );

CREATE TABLE IF NOT EXISTS session_temporal_generations (
    session_id TEXT NOT NULL,
    generation INTEGER NOT NULL,
    state TEXT NOT NULL
 );

CREATE TABLE batch_items (
                id INTEGER PRIMARY KEY,
                label TEXT NOT NULL UNIQUE
            );

CREATE TABLE configuration_format (
                    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
                    format_revision INTEGER NOT NULL
                 );

CREATE TABLE configuration_format (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    format_revision INTEGER NOT NULL CHECK (format_revision = 1)
);

CREATE TABLE configuration_revisions (
                    revision_id TEXT NOT NULL PRIMARY KEY,
                    legacy_payload TEXT NOT NULL
                 );

CREATE TABLE items (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                label TEXT NOT NULL UNIQUE
            );

CREATE TABLE observations (
                 observation_id TEXT PRIMARY KEY,
                 observation_json TEXT NOT NULL
             );

CREATE TABLE observations (
                sequence INTEGER PRIMARY KEY AUTOINCREMENT,
                observation_id TEXT NOT NULL UNIQUE,
                observation_json TEXT NOT NULL
             );

CREATE TABLE session_occurrences (
                session_id TEXT, generation INTEGER, occurrence_id TEXT,
                retrieval_anchor_id TEXT, thread_id TEXT, message_id TEXT,
                knowledge_at INTEGER, source_sequence INTEGER,
                projection_output_ordinal INTEGER
             );

CREATE TABLE session_occurrences_fts (
            index_text TEXT NOT NULL,
            snippet_text TEXT NOT NULL
        );

CREATE TABLE session_schema_migrations (
                name TEXT NOT NULL PRIMARY KEY,
                version INTEGER NOT NULL,
                applied_at INTEGER NOT NULL DEFAULT (unixepoch())
            );

CREATE TABLE session_temporal_generations (
                session_id TEXT NOT NULL,
                generation INTEGER NOT NULL,
                state TEXT NOT NULL,
                PRIMARY KEY(session_id, generation)
             );

CREATE TABLE session_temporal_generations (
                session_id TEXT NOT NULL,
                generation INTEGER NOT NULL,
                state TEXT NOT NULL,
                frozen_watermarks_json TEXT NOT NULL
             );

CREATE TABLE session_temporal_generations (
                session_id TEXT NOT NULL,
                generation INTEGER NOT NULL,
                state TEXT NOT NULL
             );

CREATE TABLE session_temporal_schema_migrations (
            name TEXT PRIMARY KEY,
            incompatible_version TEXT NOT NULL,
            applied_at INTEGER NOT NULL
         );

CREATE TABLE sessions (
                 session_id TEXT PRIMARY KEY,
                 provider TEXT NOT NULL,
                 project_key TEXT,
                 project_path TEXT
             );

CREATE TABLE sessions (
                provider TEXT NOT NULL,
                session_id TEXT NOT NULL,
                PRIMARY KEY(provider, session_id)
            );

CREATE TABLE sessions (
                provider TEXT NOT NULL,
                session_id TEXT NOT NULL,
                project_key TEXT NOT NULL,
                PRIMARY KEY(provider, session_id)
             );

CREATE TABLE sessions (
             provider TEXT NOT NULL,
             session_id TEXT NOT NULL,
             project_key TEXT NOT NULL,
             PRIMARY KEY(provider, session_id)
         );

CREATE TRIGGER semantic_vector_replay_stage_identity_guard
             BEFORE INSERT ON graph_publication_replay_v1 BEGIN
                 SELECT RAISE(ABORT, 'retired staging guard');
             END;

CREATE VIRTUAL TABLE IF NOT EXISTS lcm_raw_messages_fts USING fts5(
        index_text, role, kind, model, tool_names,
        content='lcm_raw_messages',
        content_rowid='store_id'
    );

CREATE VIRTUAL TABLE session_occurrences_fts USING fts5(
                 index_text,
                 content = 'session_occurrences',
                 content_rowid = 'rowid'
             );

