UPDATE session_temporal_generations
   SET state = 'active', activated_at = 1
 WHERE session_id = 'session.graph-stale' AND generation = 1;

UPDATE session_temporal_generations
   SET state = 'active', activated_at = 2
 WHERE session_id = 'session.graph-stale' AND generation = 2;

UPDATE session_temporal_generations
   SET state = 'ready', ready_at = 1
 WHERE session_id = 'session.graph-stale' AND generation = 1;

UPDATE session_temporal_generations
   SET state = 'ready', ready_at = 2
 WHERE session_id = 'session.graph-stale' AND generation = 2;

UPDATE session_temporal_generations
   SET state = 'superseded', completed_at = 2
 WHERE session_id = 'session.graph-stale' AND generation = 1;

CREATE INDEX idx_observations_session_sequence
ON observations (
   json_extract(observation_json, '$.identity.source.session_id'),
   sequence
);

CREATE INDEX idx_session_occurrences_generation_order
   ON session_occurrences(
       session_id, generation, knowledge_at, occurrence_id
   );

CREATE INDEX idx_session_occurrences_root_generation_order
   ON session_occurrences(
       knowledge_at DESC, session_id, occurrence_id, generation
   );

CREATE TABLE lcm_raw_messages (
    store_id INTEGER PRIMARY KEY AUTOINCREMENT,
    content TEXT,
    placeholder_text TEXT
);

CREATE TABLE observation_projection_dispositions (
   projector_version TEXT NOT NULL,
   observation_id TEXT NOT NULL,
   reason TEXT NOT NULL,
   PRIMARY KEY(projector_version, observation_id)
);

CREATE TABLE observations (
    observation_id TEXT PRIMARY KEY,
    observation_json TEXT NOT NULL
);

CREATE TABLE project_aliases (
   alias_path TEXT PRIMARY KEY,
