    AFTER INSERT ON lcm_raw_messages BEGIN
        INSERT INTO lcm_raw_messages_fts(rowid, index_text, role, kind, model, tool_names)
        VALUES (NEW.store_id, NEW.index_text, NEW.role, NEW.kind, NEW.model, NEW.tool_names);
    END;

