    AFTER UPDATE ON lcm_raw_messages BEGIN
        INSERT INTO lcm_raw_messages_fts(
            lcm_raw_messages_fts, rowid, index_text, role, kind, model, tool_names
        )
        VALUES (
            'delete', OLD.store_id, OLD.index_text, OLD.role, OLD.kind, OLD.model,
            OLD.tool_names
