CREATE TABLE IF NOT EXISTS graph_verified_heads_v1 (
    shard_id TEXT NOT NULL,
    namespace TEXT NOT NULL,
    projection TEXT NOT NULL,
    replay_sequence INTEGER NOT NULL UNIQUE
        REFERENCES graph_publication_replay_v1(sequence) ON DELETE RESTRICT,
    recovered_digest TEXT NOT NULL,
    PRIMARY KEY (shard_id, namespace, projection)
) STRICT;

CREATE TABLE remote_node_identity (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    brain_id TEXT NOT NULL,
    profile_id TEXT NOT NULL,
    node_id TEXT NOT NULL
) STRICT;

CREATE TABLE remote_query_policies (
    scope_digest TEXT NOT NULL PRIMARY KEY,
    policy_revision INTEGER NOT NULL CHECK (policy_revision > 0),
    record_json TEXT NOT NULL CHECK (json_valid(record_json))
) STRICT;

CREATE TABLE remote_recovery_authorities (
    authority_key TEXT NOT NULL PRIMARY KEY,
    authority_json TEXT NOT NULL CHECK (json_valid(authority_json)),
    frontier_sequence INTEGER NOT NULL CHECK (frontier_sequence >= 0),
    updated_at INTEGER NOT NULL
) STRICT;

CREATE TABLE remote_replay_policies (
    scope_digest TEXT NOT NULL PRIMARY KEY,
    policy_revision INTEGER NOT NULL CHECK (policy_revision > 0),
    evidence_json TEXT NOT NULL CHECK (json_valid(evidence_json))
) STRICT;

CREATE TABLE remote_replay_recovery_lease (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    lease_id TEXT NOT NULL,
    acquired_at INTEGER NOT NULL,
    expires_at INTEGER NOT NULL CHECK (expires_at > acquired_at)
) STRICT;

CREATE TRIGGER IF NOT EXISTS configuration_revisions_immutable_update
BEFORE UPDATE ON configuration_revisions
BEGIN SELECT RAISE(ABORT, 'configuration revisions are immutable'); END;

CREATE INDEX IF NOT EXISTS idx_memory_v2_current_search
         ON memory_v2_current_facts(
             owner_kind, project_id, updated_at DESC, fact_id
         );

CREATE TABLE IF NOT EXISTS git_history_session_change (
             sequence INTEGER PRIMARY KEY AUTOINCREMENT,
             provider TEXT NOT NULL,
             session_id TEXT NOT NULL,
             UNIQUE(provider, session_id)
         );

CREATE TABLE IF NOT EXISTS metadata (
        key TEXT NOT NULL PRIMARY KEY,
        value TEXT NOT NULL
    );

CREATE TABLE IF NOT EXISTS session_schema_migrations (
            name TEXT NOT NULL PRIMARY KEY,
            version INTEGER NOT NULL,
            applied_at INTEGER NOT NULL DEFAULT (unixepoch())
        );

CREATE TEMP TABLE IF NOT EXISTS observation_projection_predecessor_cleared_outputs (
            output_provider TEXT NOT NULL,
            output_message_id TEXT NOT NULL,
            PRIMARY KEY(output_provider, output_message_id)
         );

CREATE TEMP TABLE IF NOT EXISTS observation_projection_rebuild_retained_outputs (
            output_provider TEXT NOT NULL,
            output_message_id TEXT NOT NULL,
            PRIMARY KEY(output_provider, output_message_id)
         );

CREATE TRIGGER fail_analytics_batch
             BEFORE INSERT ON analytics_events
             WHEN NEW.event_kind = 'force_failure'
             BEGIN
                 SELECT RAISE(ABORT, 'forced analytics failure');
             END;

CREATE TRIGGER fail_analytics_cursor
             BEFORE INSERT ON parse_offsets
             WHEN NEW.file_path = 'hook_analytics:fixture'
             BEGIN
                 SELECT RAISE(ABORT, 'forced cursor failure');
             END;

CREATE TRIGGER fail_code_project_update
             BEFORE UPDATE ON code_projects
             BEGIN
               SELECT RAISE(ABORT, 'injected code project write failure');
             END;

CREATE TRIGGER fail_git_index_terminal_receipt
             BEFORE INSERT ON git_index_transaction_receipts
             BEGIN
                SELECT RAISE(ABORT, 'injected terminal receipt failure');
             END;

CREATE TRIGGER memory_v2_automatic_fact_receipts_no_update
             BEFORE UPDATE ON memory_v2_automatic_fact_receipts BEGIN
                 SELECT RAISE(ABORT, 'memory_v2 automatic fact receipts are immutable');
             END;

CREATE TRIGGER memory_v2_operation_receipts_no_delete
             BEFORE DELETE ON memory_v2_operation_receipts BEGIN
                 SELECT RAISE(ABORT, 'memory_v2 operation receipts are immutable');
             END;

CREATE TRIGGER memory_v2_operation_receipts_no_update
             BEFORE UPDATE ON memory_v2_operation_receipts BEGIN
                 SELECT RAISE(ABORT, 'memory_v2 operation receipts are immutable');
             END;

CREATE VIRTUAL TABLE IF NOT EXISTS lcm_raw_messages_fts USING fts5(
        index_text, role, kind, model, tool_names,
        content='lcm_raw_messages',
        content_rowid='store_id'
    );

