CREATE UNIQUE INDEX IF NOT EXISTS idx_observability_event_idempotency
    ON analytics_events(provider, project_id, hint_id)
    WHERE provider = 'tracedecay-observability' AND hint_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_session_temporal_generations_one_active
    ON session_temporal_generations(session_id)
    WHERE state = 'active';

CREATE VIRTUAL TABLE IF NOT EXISTS session_occurrences_fts USING fts5(
    index_text,
    content='session_occurrences',
    content_rowid='rowid'
);

CREATE VIRTUAL TABLE IF NOT EXISTS session_summary_nodes_fts USING fts5(
    summary_text,
    content='session_summary_nodes',
    content_rowid='rowid'
);

CREATE INDEX IF NOT EXISTS idx_external_source_acquisition_ready_v1
    ON external_source_acquisition_queue_v1(not_before_micros, binding_id)
    WHERE not_before_micros IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_lcm_summary_convergence_due
    ON lcm_summary_convergence_queue(
        next_attempt_at_ms, attempt_generation, queue_id
    )
    WHERE state IN ('pending', 'retryable');

CREATE INDEX IF NOT EXISTS work_blocked_intervals_observation_scan_v1
    ON work_blocked_intervals_v1 (
        project_id, repository_id, worktree_id, actor_id, policy_digest,
        settled, observability_durable, started_at, task_id, run_id, attempt_id, step_id,
        cause_authority_version
    );

CREATE TABLE IF NOT EXISTS authorized_scope_sets_v1 (
    scope_set_id TEXT PRIMARY KEY NOT NULL,
    revision INTEGER NOT NULL CHECK (revision > 0),
    digest TEXT NOT NULL,
    canonical_payload BLOB NOT NULL
) STRICT;

CREATE TABLE IF NOT EXISTS external_source_acquisition_queue_v1 (
    binding_id TEXT NOT NULL PRIMARY KEY,
    state_digest TEXT NOT NULL,
    not_before_micros INTEGER,
    state_json TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS external_source_frontiers_v1 (
    binding_id TEXT NOT NULL,
    frontier_digest TEXT NOT NULL,
    frontier_json TEXT NOT NULL,
    PRIMARY KEY (binding_id, frontier_digest)
);

CREATE TABLE IF NOT EXISTS external_source_projected_objects_v2 (
    binding_id TEXT NOT NULL,
    native_object_digest TEXT NOT NULL,
    mutation_digest TEXT NOT NULL,
    PRIMARY KEY (binding_id, native_object_digest)
);

CREATE TABLE configuration_format (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
