CREATE TRIGGER IF NOT EXISTS native_integration_previews_immutable_update
BEFORE UPDATE ON native_integration_previews
BEGIN
    SELECT RAISE(ABORT, 'native integration previews are immutable');
END;

CREATE INDEX IF NOT EXISTS idx_memory_v2_operation_receipts_fact
    ON memory_v2_operation_receipts(
        fact_id, owner_kind, project_id, recorded_at
    );

CREATE INDEX IF NOT EXISTS memory_v2_assertion_payload_digests_lookup
    ON memory_v2_assertion_payload_digests(
        owner_kind, project_id, content_digest, fact_id
    );

CREATE TRIGGER IF NOT EXISTS memory_v2_assertion_payload_digests_no_update
BEFORE UPDATE ON memory_v2_assertion_payload_digests BEGIN
    SELECT RAISE(ABORT, 'memory_v2 assertion payload digests are immutable');
END;

CREATE TRIGGER IF NOT EXISTS memory_v2_facts_no_update
BEFORE UPDATE ON memory_v2_facts BEGIN
    SELECT RAISE(ABORT, 'memory_v2 fact identities are immutable');
END;

CREATE TRIGGER IF NOT EXISTS memory_v2_payloads_no_update
BEFORE UPDATE ON memory_v2_assertion_payloads BEGIN
    SELECT RAISE(ABORT, 'memory_v2 assertion payloads are immutable');
END;

CREATE INDEX IF NOT EXISTS idx_generation_diagnostics_file_generation_state_anchor
    ON generation_diagnostics (
        file_occurrence_id, generation_id, record_state, diagnostic_anchor
    );

CREATE UNIQUE INDEX IF NOT EXISTS idx_diagnostic_generation_current
    ON diagnostic_generation_publications (record_state)
    WHERE record_state = 'current';

CREATE INDEX IF NOT EXISTS work_attempt_effect_holders_leak_scan_v1
ON work_attempt_effect_holders_v1 (
    project_id, repository_id, worktree_id, actor_id, policy_digest,
    resolution, deadline, dispatched_at, task_id, run_id, attempt_id
);

CREATE INDEX IF NOT EXISTS work_duplicate_adjudications_generations_v1
ON work_duplicate_adjudications_v1 (
    project_id, repository_id, worktree_id, actor_id, policy_digest,
    work_generation, topology_generation, relation_digest, revision
);

CREATE TABLE IF NOT EXISTS graph_verified_heads_v1 (
    shard_id TEXT NOT NULL,
    namespace TEXT NOT NULL,
    projection TEXT NOT NULL,
    replay_sequence INTEGER NOT NULL UNIQUE
        REFERENCES graph_publication_replay_v1(sequence) ON DELETE RESTRICT,
    recovered_digest TEXT NOT NULL,
    PRIMARY KEY (shard_id, namespace, projection)
) STRICT;

CREATE TRIGGER IF NOT EXISTS configuration_revisions_immutable_update
BEFORE UPDATE ON configuration_revisions
BEGIN SELECT RAISE(ABORT, 'configuration revisions are immutable'); END;

CREATE TABLE IF NOT EXISTS finalization_state (
                singleton INTEGER PRIMARY KEY CHECK(singleton = 1),
                state BLOB NOT NULL
            );

CREATE TABLE clone_body_payloads (
    ordinal INTEGER PRIMARY KEY,
    payload_digest BLOB NOT NULL UNIQUE,
    payload BLOB NOT NULL
);

CREATE TABLE clone_exact_postings (
    class INTEGER NOT NULL,
    normalization_revision INTEGER NOT NULL,
    digest BLOB NOT NULL,
    occurrence_ordinal INTEGER NOT NULL,
    PRIMARY KEY(class, normalization_revision, digest, occurrence_ordinal)
);

CREATE TABLE clone_fingerprint_postings (
    language TEXT NOT NULL,
    class INTEGER NOT NULL,
    normalization_revision INTEGER NOT NULL,
    fingerprint INTEGER NOT NULL,
    posting_count INTEGER NOT NULL CHECK(posting_count > 0),
    postings BLOB NOT NULL,
    PRIMARY KEY(language, class, normalization_revision, fingerprint)
);

CREATE TABLE clone_fingerprint_postings_pages (
    language TEXT NOT NULL,
    class INTEGER NOT NULL,
    normalization_revision INTEGER NOT NULL,
    fingerprint INTEGER NOT NULL,
    occurrence_ordinal INTEGER NOT NULL,
    token_position INTEGER NOT NULL
);

CREATE TABLE content_epoch (
    singleton INTEGER PRIMARY KEY CHECK(singleton = 1),
    epoch INTEGER NOT NULL CHECK(epoch >= 0)
);

CREATE TABLE exact_postings (
    term_id INTEGER NOT NULL,
    field INTEGER NOT NULL,
    documents BLOB NOT NULL,
    PRIMARY KEY(term_id, field)
);

CREATE TABLE exact_vocabulary (
    term_id INTEGER PRIMARY KEY,
    term BLOB NOT NULL
);

CREATE TABLE field_stats (
    field INT NOT NULL PRIMARY KEY,
    total_length INTEGER NOT NULL
);

CREATE TABLE field_stats_staging (
    field INT NOT NULL PRIMARY KEY,
    total_length INTEGER NOT NULL
);

CREATE TABLE row_blocks (
    first_document INTEGER PRIMARY KEY,
    payload BLOB NOT NULL
);

CREATE TABLE row_chunk_pages (
    document_id INTEGER PRIMARY KEY,
    chunk_id BLOB NOT NULL
);

CREATE TABLE row_chunks (
    chunk_id BLOB NOT NULL PRIMARY KEY,
    document_id INTEGER NOT NULL
);

CREATE TABLE row_dictionary (
    entry_id INTEGER PRIMARY KEY,
    entry BLOB NOT NULL,
    page_references INTEGER NOT NULL CHECK(page_references > 0)
);

CREATE TABLE row_dictionary_pages (
    page_ordinal INTEGER NOT NULL,
    entry_id INTEGER NOT NULL,
    entry BLOB NOT NULL,
    PRIMARY KEY(page_ordinal, entry_id)
);

CREATE TABLE term_postings (
    term TEXT NOT NULL PRIMARY KEY,
    in_fuzzy INTEGER NOT NULL CHECK(in_fuzzy IN (0, 1)),
    lists BLOB NOT NULL
);

CREATE TABLE IF NOT EXISTS commit_child (
    id INTEGER PRIMARY KEY,
    parent_id INTEGER NOT NULL
        REFERENCES commit_parent(id) DEFERRABLE INITIALLY DEFERRED
);
